head.b:skin:
:root {
    --bg: #0a0a0a;
    --card: #111111;
    --volt: #d4ff00; /* Electric Volt */
    --graphite: #2d2d2d;
    --text: #ffffff;
    --border: #1f1f1f;
}

body { 
    background: var(--bg); 
    color: var(--text); 
    font-family: 'Plus Jakarta Sans', sans-serif; 
    margin: 0; 
    padding: 20px; 
    transition: 0.5s cubic-bezier(0.4, 0, 0.2, 1); 
}

.container { max-width: 1200px; margin: 0 auto; transition: 0.5s; }

/* Zen Focus Mode */
.zen-active .config-panel { opacity: 0; pointer-events: none; transform: scale(0.95); display: none; }
.zen-active .main-grid { grid-template-columns: 1fr; }
.zen-active .container { max-width: 850px; }

header { 
    display: flex; 
    justify-content: space-between; 
    align-items: flex-end; 
    border-bottom: 2px solid var(--graphite); 
    padding-bottom: 25px; 
    margin-bottom: 40px; 
}
.brand h1 { margin: 0; font-size: 1.6rem; letter-spacing: -1px; font-weight: 800; }
.brand h1 span { color: var(--volt); }
.brand p { margin: 0; font-size: 0.65rem; font-weight: 900; color: #444; letter-spacing: 3px; text-transform: uppercase; }

.main-grid { display: grid; grid-template-columns: 380px 1fr; gap: 35px; }

.config-panel { 
    background: var(--card); 
    border-radius: 24px; 
    padding: 35px; 
    border: 1px solid var(--border); 
    position: sticky; 
    top: 20px; 
    height: fit-content;
    box-shadow: 0 10px 30px rgba(0,0,0,0.5);
}

.zen-btn { 
    background: transparent; 
    color: var(--volt); 
    border: 1px solid var(--volt); 
    padding: 8px 22px; 
    border-radius: 30px; 
    font-size: 0.65rem; 
    font-weight: 900; 
    cursor: pointer; 
    transition: 0.3s;
}
.zen-btn:hover { background: var(--volt); color: #000; }

label { 
    display: block; 
    font-size: 0.6rem; 
    font-weight: 800; 
    color: #888; 
    text-transform: uppercase; 
    letter-spacing: 2px; 
    margin: 20px 0 8px 0; 
}

input, select { 
    width: 100%; 
    background: #000; 
    border: 1px solid var(--border); 
    color: white; 
    padding: 15px; 
    border-radius: 12px; 
    font-size: 0.85rem; 
    box-sizing: border-box; 
    outline: none;
}
input:focus { border-color: var(--volt); }

.btn-primary { 
    width: 100%; 
    background: var(--volt); 
    color: #000; 
    border: none; 
    padding: 18px; 
    border-radius: 12px; 
    font-weight: 900; 
    cursor: pointer; 
    margin-top: 30px; 
    text-transform: uppercase; 
    letter-spacing: 1px;
}

.output-area { 
    background: #050505; 
    border-radius: 24px; 
    padding: 35px; 
    min-height: 750px; 
    border: 1px solid var(--border); 
}

.placeholder-text { 
    text-align: center; 
    margin-top: 320px; 
    color: #111; 
    font-weight: 900; 
    letter-spacing: 12px; 
    text-transform: uppercase; 
    font-size: 1.4rem; 
}

.result-card { 
    background: #0f0f0f; 
    padding: 30px; 
    border-radius: 20px; 
    margin-bottom: 30px; 
    border-left: 4px solid var(--volt); 
    position: relative; 
    animation: slideIn 0.5s ease;
}

@keyframes slideIn { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }

.copy-btn { 
    position: absolute; 
    top: 25px; 
    right: 25px; 
    background: #000; 
    color: var(--volt); 
    border: 1px solid var(--volt); 
    padding: 8px 16px; 
    border-radius: 8px; 
    font-size: 0.6rem; 
    font-weight: 900; 
    cursor: pointer; 
}
.copy-btn:hover { background: var(--volt); color: #000; }

pre { font-family: 'Monaco', monospace; font-size: 0.8rem; color: #aaa; white-space: pre-wrap; margin: 0; margin-top: 15px; line-height: 1.6; }
.tag { color: var(--volt); font-size: 0.6rem; font-weight: 900; letter-spacing: 1.5px; text-transform: uppercase; }

footer { margin-top: 100px; padding: 40px; border-top: 1px solid var(--graphite); text-align: center; }
footer span { color: #222; font-weight: 900; letter-spacing: 5px; font-size: 0.75rem; text-transform: uppercase; }

body.script:
//
function toggleZen() {
  document.body.classList.toggle('zen-active');
}

function resetApp() {
  if(confirm("Hapus semua desain kaos?")) {
    document.getElementById('theme').value = "";
    document.getElementById('output').innerHTML = '<div class="placeholder-text">STICKER FORGE 2026</div>';
  }
}

function forgeTee() {
  const theme = document.getElementById('theme').value || "Urban Spirit";
  const sty = document.getElementById('style').value;
  const place = document.getElementById('placement').value;
  const col = document.getElementById('colors').value;
  const out = document.getElementById('output');

  out.innerHTML = "";

  const prompts = [
    {
      tag: "APPAREL GRAPHIC PROMPT",
      text: `Professional t-shirt design graphic for "${theme}". \nStyle: ${sty}.\nPlacement Concept: ${place}.\nColor Scheme: ${col}.\n\nTechnical: Vector-ready, clean separation, screen-print compatible, high contrast, professional streetwear aesthetic, 8k resolution, flat background for easy mockup. --v 6.1`
    },
    {
      tag: "LIFESTYLE MOCKUP CONCEPT",
      text: `A professional streetwear mockup of a high-quality cotton t-shirt featuring ${theme} design in ${sty} style. Positioned as ${place}. Using ${col}. Soft studio lighting, realistic fabric textures, editorial fashion photography style.`
    }
  ];

  prompts.forEach(p => {
    let card = document.createElement('div');
    card.className = 'result-card';

    let tag = document.createElement('div');
    tag.className = 'tag';
    tag.innerText = p.tag;

    let btn = document.createElement('button');
    btn.className = 'copy-btn';
    btn.innerText = 'COPY';
    btn.onclick = () => {
      navigator.clipboard.writeText(p.text);
      btn.innerText = 'DONE';
      setTimeout(() => { btn.innerText = 'COPY'; }, 1500);
    };

    let pre = document.createElement('pre');
    pre.innerText = p.text;

    card.appendChild(tag);
    card.appendChild(btn);
    card.appendChild(pre);
    out.appendChild(card);
  });
}
//
